  ('art_0f9bd0b056f799756e83', 'monochrome-gothic-printmaking', 'Monochrome Gothic Printmaking', 'Detailed linocut print of a gothic cathedral cathedral facade with dramatic black ink shading and linework', 'Detailed linocut print of a gothic cathedral cathedral facade with dramatic black ink shading and linework. Monochrome Gothic Printmaking. Gothic figures, ruins, forests, and symbols rendered through black-and-white relief printing, cross-hatching, and carved shadow. Palette: black, ivory, graphite. Lighting: graphic white cuts against dense black; candle-like highlight zones. Linework and edges: print-defined contours with visible ink breakup, carved or stippled shading, and tactile edge irregularity. Medium and texture: woodcut, linocut, engraving, cross-hatch, rough paper. Composition and motion: vertical cathedral forms; central apparition; decorative border or vignette; dense shadow masses. Positive style cues: gothic printmaking, monochrome woodcut, linocut texture, cross-hatching, medieval darkness, stark chiaroscuro, haunted forest, carved linework, antique paper.', 'repeatable', 1000, 'USD', 'v1', true, transaction_timestamp(), transaction_timestamp(), transaction_timestamp(), 'artworks/art_0f9bd0b056f799756e83/base', 'assets/artworks/monochrome-gothic-printmaking.jpg', 'monochrome-gothic-printmaking', 'Graphic / Illustration / Print', 91, 'Detailed linocut print of a gothic cathedral cathedral facade with dramatic black ink shading and linework', array['monochrome', 'gothic', 'print']::text[], array['gothic printmaking', 'monochrome woodcut', 'linocut texture', 'cross-hatching', 'medieval darkness', 'stark chiaroscuro', 'haunted forest', 'carved linework', 'antique paper']::text[], array['smooth digital painting', 'full color', 'soft pastel', 'clean vector curves', 'glossy photography', 'modern minimalist architecture']::text[], array['black', 'ivory', 'graphite']::text[], 'graphic white cuts against dense black; candle-like highlight zones', 'woodcut,